import json,numpy as np,hashlib,zipfile
from pathlib import Path
p=Path('/mnt/data/stage19_final_gate');sy=json.load(open(p/'SYMMETRY_SCREEN.json'))['penrose'];P=np.array(sy['period_basis']);A=np.linalg.inv(P.T);B=P.T;bound=np.linalg.norm(A,axis=1)[:,None]*np.linalg.norm(B,axis=0)[None,:];S={}
for k in ('square','penrose'):
 z=np.load(p/f'{k}_full_auxiliary_seed101.npz');expected=22801 if k=='square' else 22808
